1	package cli
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"path/filepath"
8		"reflect"
9		"strings"
10		"testing"
11	
12		"github.com/entireio/entire-graph/internal/sem"
13		scippb "github.com/scip-code/scip/bindings/go/scip"
14		"google.golang.org/protobuf/proto"
15	)
16	
17	// adr0005Path is the RFD whose freshness contract tells peregrine how to decide
18	// per-language whether to trust the SCIP feed. It is checked against the code the
19	// same way AGENTS.md is (see agentguide_test.go): a design document that other
20	// teams implement against is only useful while it describes the artifact that
21	// actually ships.
22	const adr0005Path = "0005-converge-code-search.md"
23	
24	// adr0005FreshnessItem2 returns the freshness-contract item that describes what
25	// the omission note carries, isolated from the rest of the RFD so a field name
26	// mentioned in some unrelated paragraph cannot satisfy the check below.
27	func adr0005FreshnessItem2(t *testing.T) string {
28		t.Helper()
29		raw, err := os.ReadFile(filepath.Join("..", "..", "docs", "adr", adr0005Path))
30		if err != nil {
31			t.Fatal(err)
32		}
33		text := string(raw)
34		const start = "2. Per-language trust is driven by the omission note"
35		begin := strings.Index(text, start)
36		if begin < 0 {
37			t.Fatalf("%s no longer has a freshness-contract item 2; this test is pinned to it", adr0005Path)
38		}
39		end := strings.Index(text[begin:], "\n3. ")
40		if end < 0 {
41			t.Fatalf("%s freshness-contract item 2 has no item 3 after it", adr0005Path)
42		}
43		return text[begin : begin+end]
44	}
45	
46	// TestADR0005NamesTheFailureRecordItActuallyGets is the docs/spec consistency
47	// check for a mismatch that was live: item 2 said "only records say which
48	// language and which file", so a consumer reading the RFD would have gone
49	// looking for a language on a failure record that has never had one. It listed
50	// the record as carrying "path and code" while the shipped record is five
51	// fields.
52	//
53	// The assertion is deliberately driven off the struct rather than off a fixed
54	// list: adding a field to sem.PartialFailure (a `language`, one day) makes this
55	// fail until the RFD paragraph that describes the record is brought with it,
56	// which is the direction the drift actually runs.
57	func TestADR0005NamesTheFailureRecordItActuallyGets(t *testing.T) {
58		t.Parallel()
59		item := adr0005FreshnessItem2(t)
60		recordType := reflect.TypeOf(sem.PartialFailure{})
61		named := 0
62		for i := range recordType.NumField() {
63			tag := strings.Split(recordType.Field(i).Tag.Get("json"), ",")[0]
64			if tag == "" || tag == "-" {
65				continue
66			}
67			named++
68			if !strings.Contains(item, "`"+tag+"`") {
69				t.Errorf("the RFD's per-language fallback contract never names `%s`, which every failure record "+
70					"in the feed carries; a consumer implementing from this paragraph does not know the field is there",
71					tag)
72			}
73		}
74		if named == 0 {
75			t.Fatal("sem.PartialFailure has no JSON fields; this test asserted nothing")
76		}
77		// The specific false claim. A record with no language field cannot be the
78		// thing that says which language, and saying it does sends the consumer
79		// after a field to read instead of the join it has to perform.
80		if _, hasLanguage := recordType.FieldByNameFunc(func(name string) bool { return name == "Language" }); !hasLanguage {
81			if strings.Contains(item, "records say which language") {
82				t.Error("the RFD still says the failure records say which language, and sem.PartialFailure has no " +
83					"language field")
84			}
85		}
86	}
87	
88	// TestSCIPFeedResolvesAFailingFilesLanguage is the mechanism the corrected
89	// paragraph prescribes, run end to end: a consumer holding only the artifact
90	// pair must be able to get from a failure record to the language it should stop
91	// trusting. It joins partial_failures[].file_path to the SCIP Document of the
92	// same relative_path and reads that Document's language.
93	//
94	// It is the reason the RFD was corrected towards the implementation rather than
95	// the other way round: the information the contract needs is already in the
96	// artifact, so no field and no format bump is required to deliver it.
97	func TestSCIPFeedResolvesAFailingFilesLanguage(t *testing.T) {
98		t.Parallel()
99		repo := t.TempDir()
100		write(t, repo, "main.go", "package sample\n\nfunc caller() { callee() }\nfunc callee() {}\n")
101		// One very long line is what the provider calls minified, so this produces a
102		// real E_MINIFIED failure record naming a TypeScript file without needing a
103		// multi-megabyte fixture.
104		write(t, repo, "bundle.ts", "export const bundled="+strings.Repeat("\"x\"+", 4000)+"\"x\";\n")
105	
106		var stdout, stderr bytes.Buffer
107		if err := Run(t.Context(), Options{
108			Version: "scip-test",
109			Env:     EntireEnv{RepoRoot: repo},
110			Stdout:  &stdout,
111			Stderr:  &stderr,
112		}, []string{"snapshot", "--repo", repo, "--worktree", "--format", "scip"}); err != nil {
113			t.Fatal(err)
114		}
115		var note sem.SCIPOmissionNote
116		if err := json.Unmarshal(bytes.TrimSpace(stderr.Bytes()), &note); err != nil {
117			t.Fatalf("stderr omission note is not JSON: %q: %v", stderr.String(), err)
118		}
119		if len(note.PartialFailures) == 0 {
120			t.Fatalf("fixture produced no failure record, so the join is not exercised: %#v", note)
121		}
122		var index scippb.Index
123		if err := proto.Unmarshal(stdout.Bytes(), &index); err != nil {
124			t.Fatalf("scip output is not a valid Index protobuf: %v", err)
125		}
126		documents := map[string]*scippb.Document{}
127		for _, doc := range index.GetDocuments() {
128			documents[doc.GetRelativePath()] = doc
129		}
130		joined := 0
131		for _, failure := range note.PartialFailures {
132			if failure.FilePath == "" {
133				continue
134			}
135			doc := documents[failure.FilePath]
136			if doc == nil {
137				t.Errorf("failure %s names %q and the index has no document for it, so a consumer cannot tell which "+
138					"language to stop trusting", failure.Code, failure.FilePath)
139				continue
140			}
141			if doc.GetLanguage() == "" {
142				t.Errorf("failure %s names %q whose document carries no language", failure.Code, failure.FilePath)
143				continue
144			}
